struct Song {
    let title: String
    let duration: Int
}

let track = Song(title: "Cardigan", duration: 240)
let path = \Song.title
print(track[keyPath: path])

struct UserAccount {
    let username: String
    var loginCount: Int
}

var account = UserAccount(username: "swiftdev", loginCount: 3)
let countPath: WritableKeyPath<UserAccount, Int> = \UserAccount.loginCount
account[keyPath: countPath] += 1
print(account.loginCount)

struct Fruit {
    let name: String
}

let basket = [Fruit(name: "Apple"), Fruit(name: "Banana"), Fruit(name: "Cherry")]
let names = basket.map(\.name)
print(names.joined(separator: "-"))

struct Address {
    var city: String
}

struct Contact {
    var address: Address
}

var contact = Contact(address: Address(city: "Boston"))
let cityPath = \Contact.address.city
contact[keyPath: cityPath] = "New York"
print(contact.address.city)

struct Employee {
    let name: String
    let isManager: Bool
}

let staff = [
    Employee(name: "Alice", isManager: true),
    Employee(name: "Bob", isManager: false),
    Employee(name: "Charlie", isManager: true)
]

let managers = staff.filter(\.isManager).map(\.name)
print(managers.joined(separator: " & "))

final class VehicleRecord {
    var mileage: Int
    init(mileage: Int) { self.mileage = mileage }
}

let car = VehicleRecord(mileage: 15000)
let path: ReferenceWritableKeyPath<VehicleRecord, Int> = \VehicleRecord.mileage
car[keyPath: path] += 500
print(car.mileage)

struct Book {
    let title: String
    var pages: Int
    var isLong: Bool {
        return pages > 300
    }
}

let novel = Book(title: "Epic", pages: 450)
let path = \Book.isLong
print(novel[keyPath: path])

struct City {
    let name: String
}
struct Company {
    var headquarters: City?
}

let startup = Company(headquarters: City(name: "Austin"))
let path: KeyPath<Company, String?> = \Company.headquarters?.name
print(startup[keyPath: path] ?? "Unknown")

